using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Xml.Linq;using System.Collections.Generic;using System.Security.Cryptography;using V15Update;
public static class OnnxUpdaterTests {
 static int count;static void Check(bool x,string name){if(!x)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);count++;}static void Reject(Action a,string name){try{a();}catch{Check(true,name);return;}throw new Exception("FAIL "+name);}
 static string Hash(byte[] b){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 public static void Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"v15-onnx-updater-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  string one=Path.Combine(root,"V15_ONNX_GPU_1.4.3_01.zip"),two=Path.Combine(root,"V15_ONNX_GPU_1.4.3_02.zip");string[] names={"sherpa-onnx-offline-tts.exe","onnxruntime.dll","onnxruntime_providers_cuda.dll","onnxruntime_providers_shared.dll"};var xml=new XElement("update",new XAttribute("product","V15VoiceStudio"),new XAttribute("version","1.4.3"),new XAttribute("kind","onnx"));
  using(var z1=ZipFile.Open(one,ZipArchiveMode.Create))using(var z2=ZipFile.Open(two,ZipArchiveMode.Create)){foreach(string n in names){byte[] a=System.Text.Encoding.UTF8.GetBytes(n+" A"),b=System.Text.Encoding.UTF8.GetBytes(n+" B");foreach(var row in new[]{new{Zip=z1,Data=a},new{Zip=z2,Data=b}})using(var s=row.Zip.CreateEntry(n).Open())s.Write(row.Data,0,row.Data.Length);var f=new XElement("file",new XAttribute("path","engine/gpu/"+n),new XAttribute("size",a.Length+b.Length),new XAttribute("sha256",Hash(a.Concat(b).ToArray())));f.Add(new XElement("piece",new XAttribute("archive",Path.GetFileName(one)),new XAttribute("entry",n),new XAttribute("size",a.Length),new XAttribute("sha256",Hash(a))),new XElement("piece",new XAttribute("archive",Path.GetFileName(two)),new XAttribute("entry",n),new XAttribute("size",b.Length),new XAttribute("sha256",Hash(b))));xml.Add(f);}using(var s=z1.CreateEntry("manifest.xml").Open())xml.Save(s);}
  var stage=Path.Combine(root,"stage");var files=UpdateEngine.Stage(one,stage,s=>{});Check(files.Count==4&&File.ReadAllText(Path.Combine(stage,"engine/gpu/onnxruntime.dll"))=="onnxruntime.dll Aonnxruntime.dll B","Multipart ONNX files reassemble in manifest order and verify SHA256");
  File.Move(two,two+".missing");Reject(()=>UpdateEngine.Stage(one,Path.Combine(root,"missing"),s=>{}),"Missing part rejected before any file is staged");Check(!Directory.GetFiles(Path.Combine(root,"missing"),"*",SearchOption.AllDirectories).Any(),"Missing-part failure leaves no partial library");File.Move(two+".missing",two);
  var folder=Path.Combine(root,"bad");Directory.CreateDirectory(folder);File.Copy(one,Path.Combine(folder,Path.GetFileName(one)));File.Copy(two,Path.Combine(folder,Path.GetFileName(two)));var bad=new XElement(xml);bad.Elements("file").First().SetAttributeValue("path","engine/gpu/../../ai/worker.py");bad.Save(Path.Combine(folder,"manifest.xml"));Reject(()=>UpdateEngine.Stage(folder,Path.Combine(root,"unsafe"),s=>{}),"Native addon cannot overwrite worker or escape isolated engine folder");
  bad=new XElement(xml);bad.Elements("file").First().Elements("piece").First().SetAttributeValue("sha256",new string('0',64));bad.Save(Path.Combine(folder,"manifest.xml"));Reject(()=>UpdateEngine.Stage(folder,Path.Combine(root,"corrupt"),s=>{}),"Bad per-piece SHA256 is rejected");
  var target=Path.Combine(root,"app");Directory.CreateDirectory(target);Directory.CreateDirectory(Path.Combine(target,"engine"));File.WriteAllText(Path.Combine(target,"engine/sherpa-onnx-offline-tts.exe"),"KEEP CPU");Directory.CreateDirectory(Path.Combine(target,"ai/gpu"));File.WriteAllText(Path.Combine(target,"ai/gpu/torch.txt"),"KEEP TORCH");UpdateEngine.Commit(stage,target,files,s=>{});Check(File.ReadAllText(Path.Combine(target,"engine/sherpa-onnx-offline-tts.exe"))=="KEEP CPU"&&File.ReadAllText(Path.Combine(target,"ai/gpu/torch.txt"))=="KEEP TORCH","Addon commit preserves original CPU and Torch CUDA runtime");
  if(args.Length>0){string real=args[0],realstage=Path.Combine(root,"real");files=UpdateEngine.Stage(real,realstage,Console.WriteLine);XElement manifest;using(var zip=ZipFile.OpenRead(real))using(var s=zip.GetEntry("manifest.xml").Open())manifest=XElement.Load(s);Check(files.Count==manifest.Elements("file").Count()&&manifest.Elements("file").All(f=>UpdateEngine.Hash(Path.Combine(realstage,(string)f.Attribute("path")))==(string)f.Attribute("sha256")),"All actual packaged native DLLs reassemble to original verified SHA256");Directory.Delete(realstage,true);}
  Directory.Delete(root,true);Console.WriteLine("TOTAL ONNX UPDATER "+count+" passed.");
 }
}
